class SFTDataCollator:
    def __init__(self, response_ids, pad_token_id):
        self.response_ids = response_ids
        self.pad_token_id = pad_token_id
    def __call__(self, batch):
        max_len = max(len(x['input_ids']) for x in batch)
        padded_inputs, padded_labels = [], []
        for x in batch:
            ids = list(x['input_ids'])
            labels = [-100] * len(ids)
            r_len = len(self.response_ids)
            for i in range(len(ids) - r_len + 1):
                if ids[i:i+r_len] == self.response_ids:
                    for j in range(i + r_len, len(ids)):
                        labels[j] = ids[j]
            pad_len = max_len - len(ids)
            padded_inputs.append(ids + [self.pad_token_id] * pad_len)
            padded_labels.append(labels + [-100] * pad_len)
        return {
            'input_ids': torch.tensor(padded_inputs),
            'labels': torch.tensor(padded_labels)
        }
